commands.command:
cat > /etc/rsyslog.d/10-inventory-collector.conf <<'ANTRIEB_EOF'
module(load="imtcp")
input(type="imtcp" port="514" ruleset="inventoryCollector")

ruleset(name="inventoryCollector") {
    if $programname == 'inventory' then {
        action(type="omfile" file="/var/log/inventory/node2.log" fileCreateMode="0644")
    }
    stop
}
ANTRIEB_EOF
rsyslogd -N1 -f /etc/rsyslog.conf && echo CONFIG_OK
